changeSet.sql:
CREATE TABLE IF NOT EXISTS word_eng ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), word VARCHAR(100) NOT NULL, CONSTRAINT word_eng_word_unique UNIQUE (word) );
CREATE TABLE IF NOT EXISTS audio ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), word_id uuid NOT NULL , file_path VARCHAR(255) NOT NULL, file_source VARCHAR(255) NOT NULL, FOREIGN KEY (word_id) REFERENCES word_eng (id) ON DELETE CASCADE ON UPDATE CASCADE, UNIQUE (file_path) );
CREATE TABLE IF NOT EXISTS transcription ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), word_id uuid NOT NULL, transcription VARCHAR(255) NOT NULL, dialect VARCHAR(10) NOT NULL, FOREIGN KEY (word_id) REFERENCES word_eng (id) ON DELETE CASCADE ON UPDATE CASCADE );
